"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$taskRoot = (Get-Location).Path
$cursor = Get-Item -LiteralPath $taskRoot
while ($null -ne $cursor) {
    $instruction = Join-Path $cursor.FullName '"'AGENTS.md'
    if (Test-Path -LiteralPath "'$instruction) {
        Write-Output $instruction
        Get-Content -LiteralPath $instruction -Encoding UTF8
    }
    $cursor = $cursor.Parent
}
Get-FileHash -LiteralPath '"'candidate.md' -Algorithm SHA256
